mapper.select:
select * from (select a.primary_key as primaryKeyValue, a.enterprise_code, a.submit_date, a.submit_user_code, c.staff_sign as submitUserName, a.submit_num, a.scrap_num, a.submit_total_num, b.inspect_num, b.passed_num, b.files, b.inspect_user, d.staff_sign as inspectUserName, b.create_time, b.remark, b.batch_no, b.check_item from ${submitTableName} a LEFT JOIN ${reportTableName} b on a.report_main_id = b.report_main_id and b.batch_no = a.batch_no and a.batch_no is not null
LEFT JOIN ${staffTableName} c on a.submit_user_code = c.primary_key LEFT JOIN ${staffTableName} d on b.inspect_user = d.primary_key where a.report_main_id = #{reportMainId} and a.submit_num > 0 ORDER BY MAX(b.create_time) OVER (PARTITION BY b.batch_no) DESC, b.batch_no, b.create_time desc ) t where t.enterprise_code = #{enterpriseCode}
and t.submit_user_code is not null
and t.submit_user_code = #{inspectUserCode}

select *
from ${reportTableName}
where enterprise_code = #{enterpriseCode}
  and report_main_id = #{reportMainId}
  and submit_user_code = #{submitUserCode}

mapper.update:
update ${reportTableName}
set status = #{status}
where report_main_id = #{reportMainId}
  and submit_user_code = #{submitUserCode}

mapper.select:
WITH t as (select count(1)
           from ${dispatcherTableName}
           where report_main_id = #{reportMainId}),
     t1 as (select count(1)
            from (select DISTINCT report_main_id, submit_user_code, status
                  from ${reportTableName}
                  where report_main_id = #{reportMainId}
                    and status = 3))
select t.* = t1.*
from t,
     t1

select count(1) > 0
from ${reportTableName}
where report_main_id = #{reportMainId}
  and enterprise_code = #{enterpriseCode}
  and status != 5
and  submit_user_code = #{submitUserCode}
